const JA_FONT = '"Noto Sans JP","Hiragino Kaku Gothic ProN","Hiragino Sans","Yu Gothic","Meiryo",sans-serif';

function shuffle<X>(a: X[]): X[] {
  const b = a.slice();
  for (let i = b.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = b[i]!;
    b[i] = b[j]!;
    b[j] = tmp;
  }
  return b;
}
function pick<X>(a: X[]): X {
  return a[Math.floor(Math.random() * a.length)]!;
}
function wpick<X>(a: X[], w: (x: X) => number): X {
  const ws = a.map(w);
  const tot = ws.reduce((s: number, x: number) => s + x, 0);
  let r = Math.random() * tot;
  for (let i = 0; i < a.length; i++) {
    r -= ws[i]!;
    if (r <= 0) return a[i]!;
  }
  return a[a.length - 1]!;
}
function uniq(a: string[]): string[] {
  return Array.from(new Set(a));
}
function deck<X>(items: X[]): () => X {
  let q: X[] = [];
  let last: X | null = null;
  return () => {
    if (q.length === 0) {
      q = shuffle(items);
      if (q.length > 1 && q[0] === last) q.push(q.shift()!);
    }
    const x = q.shift()!;
    last = x;
    return x;
  };
}
function mc(correct: string, distract: string[]): { options: string[]; answer: number } {
  const ds = uniq(distract.filter((d: string) => d && d !== correct)).slice(0, 3);
  const options = shuffle([correct, ...ds]);
  return { options, answer: options.indexOf(correct) };
}
function toKata(s: string): string {
  return Array.from(s)
    .map((ch: string) => {
      const c = ch.charCodeAt(0);
      return c >= 0x3041 && c <= 0x3096 ? String.fromCharCode(c + 0x60) : ch;
    })
    .join("");
}
const RUBY_RE = /([\u3400-\u9fff々〆ヶ]+)\[([^\]]+)\]/g;
function plain(s: string): string {
  return s.replace(RUBY_RE, "$1");
}
function kanaOf(s: string): string {
  return s.replace(RUBY_RE, "$2");
}
