type Cmp = { short: string; t: string; ask: string; pts: string[]; qs: CmpQ[] };
const CMP: Cmp[] = [];
CMP_RAW.split("\n").forEach((l: string) => {
  if (l.startsWith("#")) {
    const [short, t, ask, pts] = l.slice(1).split("|") as [string, string, string, string];
    CMP.push({ short, t, ask: ask === "-" ? "" : ask, pts: pts.split("／"), qs: [] });
    return;
  }
  const g = CMP[CMP.length - 1];
  if (!g || !l.trim()) return;
  const [s, a, d, e] = l.split("|") as [string, string, string, string];
  g.qs.push({ s: furiK(`c${CMP.length - 1}_${g.qs.length}`, s), a, d: d.split("／"), e });
});
type Gram = { id: string; pat: string; m: string; conn: string; ex: string; full: string; blank: string; ans: string; tr: string; d: string[] };
const GRAMMAR: Gram[] = GRAMMAR_RAW.split("\n").map((l: string, i: number) => {
  const [pat, m, conn, ex0, tr, d] = l.split("|") as [string, string, string, string, string, string];
  const ex = furiK("g" + i, ex0);
  const mm = ex.match(/\{(.+?)\}/);
  const ans = mm ? mm[1] ?? "" : "";
  return { id: "g" + i, pat, m, conn, ex, full: ex.replace(/\{(.+?)\}/, "$1"), blank: ex.replace(/\{.+?\}/, "（　　）"), ans, tr, d: d.split("／") };
});

type OI = { id: string; pre: string; p: string[]; post: string; star: number; tr: string };
function parseOrder(raw: string, prefix: string): OI[] {
  return raw.split("\n").map((l: string, i: number) => {
    const [pre, p, post, star, tr] = l.split("|") as [string, string, string, string, string];
    return { id: prefix + i, pre, p: p.split("／"), post, star: Number(star), tr };
  });
}
const ORDER: OI[] = parseOrder(
  `健康のために、|毎日／野菜を／食べる／ようにしている|。|2|為了健康，我盡量每天吃蔬菜。
|日本に／来た／ばかり／なので|、まだ日本語が上手ではありません。|2|因為才剛來日本，日語還不太好。
窓を|開けた／とたん／強い風が／部屋に|入ってきた。|1|一打開窗，強風就吹進了房間。
|忘れない／ように／手帳に／予定を|書いておきます。|1|為了不忘記，先把行程寫在手帳上。
この写真を|見る／たびに／楽しかった／高校時代|を思い出す。|2|每次看這張照片，就會想起快樂的高中時代。
先生が|説明した／とおりに／やって／みたら|、うまくできた。|2|照老師說明的做做看，結果成功了。
彼は|知っている／くせに／何も／教えて|くれない。|2|他明明知道，卻什麼都不告訴我。
雨が|降らない／うちに／早く／帰りましょう|。|1|趁還沒下雨，早點回家吧。
この店は|値段が／安い／わりに／料理が|おいしい。|2|這家店價格便宜，料理卻意外地好吃。
私は|来年／日本へ／留学する／ことに|しました。|2|我決定明年去日本留學。
母に|部屋を／掃除／させられて／遊びに|行けなかった。|2|被媽媽逼著打掃房間，沒辦法出去玩。
|寝坊した／せいで／大切な／会議に|遅れてしまった。|2|都怪睡過頭，重要的會議遲到了。
国|によって／食事の／マナーは／違う|そうだ。|2|聽說用餐禮儀因國家而異。
宿題を|せずに／寝て／しまった／ので|、先生に叱られた。|2|沒寫作業就睡著了，所以被老師罵。
買い物に|行く／ついでに／郵便局で／手紙を|出した。|1|去買東西時，順便在郵局寄了信。
あんなに|練習／した／のだから／負ける|わけがない。|2|練習了那麼多，不可能會輸。`,
  "o"
);
function orderLine(o: OI): string {
  return (o.pre ? o.pre + " " : "") + o.p.map((_x: string, i: number) => (i === o.star ? "＿★＿" : "＿＿＿")).join(" ") + " " + o.post;
}
function orderQ(o: OI, sec: Sec, tag: string): Q {
  const ans = o.p[o.star] ?? "";
  const full = furiK(o.id, o.pre + o.p.join("") + o.post);
  const m = mc(ans, o.p.filter((_x: string, i: number) => i !== o.star));
  return {
    id: `${sec}:${o.id}`,
    sec,
    tag,
    prompt: "把下面 4 個詞排成正確句子，★ 位置應放入哪一個？\n" + orderLine(o),
    ja: true,
    optJa: true,
    ...m,
    exp: `正確順序：${o.p.join(" → ")}\n${full}\n${o.tr}`,
    tts: full,
    ttsAfter: true,
    review: orderLine(o),
  };
}

