f|彼女は料理が得意で、いつもおいしいものを作ってくれます。|得意／苦手／退屈／迷惑|得意（とくい）：擅長。
m|もう少し早く来ればよかったのに。|要是早點來就好了（遺憾）／幸好早點來了／明天要早點來／來得太早了|～ばよかったのに：表示遺憾、後悔。
m|この薬は食事の後に飲んでください。|請在飯後吃這個藥／請在飯前吃這個藥／請在睡前吃這個藥／這個藥一天吃三次|食事の後＝飯後。
m|今、ちょうど出かけるところです。|現在正要出門／剛剛回到家／已經出門很久了／今天不打算出門|動詞辭書形＋ところだ：正要…。
f|雨が降っても、試合は行います。|行います／休みます／決まりません／始まりません|～ても：即使…也…。
f|日本の生活にもう慣れました。|慣れました／似ました／別れました／驚きました|～に慣れる：習慣…。
m|田中さんは来月、会社を辞めるらしいですよ。|田中先生下個月好像要辭職／田中先生下個月要進公司／田中先生已經辭職了／田中先生下個月要升職|～らしい：好像…（根據傳聞）。辞める（やめる）：辭職。
m|窓を開けたまま、出かけてしまいました。|窗戶開著就出門了／關好窗戶才出門／回家後打開了窗戶／窗戶壞掉打不開|た形＋まま：保持…的狀態。
f|電車が遅れて、会議に間に合いませんでした。|遅れて／進んで／戻って／届いて|遅れる：誤點；間に合う：趕上。
m|子どものころ、毎日ピアノを練習させられました。|小時候每天被迫練鋼琴／小時候每天讓別人練鋼琴／小時候很想練鋼琴／小時候不能練鋼琴|使役被動「させられる」：被迫做…。
m|この資料、明日までにコピーしておいてもらえる？|請在明天之前先把資料影印好／明天要去買影印機／資料已經影印好了／今天不用影印|～ておいてもらえる？：可以幫我先…好嗎？（口語請求）
