function kitem(c: string): KItem {
  const b = ALL_KANA.find((k: Kana) => k.h === c || k.k === c) ?? { h: c, k: c, r: romaOf(c), row: "ext" };
  return { c, r: b.r, scr: isHira(c) ? "h" : "k", base: b };
}
function fmtIn(ms: number): string {
  const m = Math.max(1, Math.round(ms / 60000));
  return m < 60 ? `${m} 分鐘後` : m < 1440 ? `${Math.round(m / 60)} 小時後` : `${Math.round(m / 1440)} 天後`;
}
function mastery(c: string): number {
  const k = DB.ks[c];
  if (!k || !k.n) return 0;
  return (k.c / k.n) * Math.min(1, k.n / 3) * (weakScore(c) > 0 ? 0.5 : 1);
}
function Bar(props: { v: number; color: string; label?: string }) {
  const t = useGrokTheme();
  const pct = Math.round(Math.max(0, Math.min(1, props.v)) * 100);
  return (
    <div role="progressbar" aria-label={props.label} aria-valuemin={0} aria-valuemax={100} aria-valuenow={pct} style={{ height: 8, borderRadius: 9, background: t.bg.subtle, overflow: "hidden", border: `1px solid ${t.border.subtle}` }}>
      <div style={{ width: `${pct}%`, height: "100%", background: props.color }} />
    </div>
  );
}
function SrsPanel() {
  const t = useGrokTheme();
  const db = useDB();
  const [on, setOn] = useState(false);
  const [, setTick] = useState(0);
  useEffect(() => {
    const id = window.setInterval(() => setTick((n: number) => n + 1), 20000);
    return () => window.clearInterval(id);
  }, []);
  const now = Date.now();
  const keys = Object.keys(db.srs);
  const due = keys.filter((c: string) => (db.srs[c]?.due ?? 0) <= now);
  const next = keys.map((c: string) => db.srs[c]?.due ?? 0).filter((d: number) => d > now).sort((a: number, b: number) => a - b)[0];
  const gen = (): Q => {
    const d = srsDue();
    const src = d.length ? d : Object.keys(DB.srs);
    const pool = (src.length ? src : ["シ", "ツ", "ソ", "ン"]).map(kitem);
    return kanaQ(pool, Math.random() < 0.5 ? "k2r" : "r2k");
  };
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Card title="間隔複習佇列（SRS）">
        <div style={{ display: "flex", gap: 18, flexWrap: "wrap", marginBottom: 8 }}>
          <div><div style={{ fontSize: 12, color: t.text.secondary }}>現在到期</div><div style={{ fontSize: 26, fontWeight: 600, color: due.length ? t.text.danger : t.text.success }}>{due.length}</div></div>
          <div><div style={{ fontSize: 12, color: t.text.secondary }}>佇列中</div><div style={{ fontSize: 26, fontWeight: 600 }}>{keys.length}</div></div>
          <div><div style={{ fontSize: 12, color: t.text.secondary }}>下一個到期</div><div style={{ fontSize: 16, fontWeight: 600, marginTop: 6 }}>{next ? fmtIn(next - now) : "—"}</div></div>
        </div>
        {due.length ? (
          <div lang="ja" style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 8, fontFamily: JA_FONT, fontSize: 20 }}>
            {due.slice(0, 60).map((c: string) => <span key={c} style={{ padding: "0 6px", border: `1px solid ${t.border.subtle}`, borderRadius: 6 }}>{c}</span>)}
          </div>
        ) : null}
        <SrsSpread />
        <Note>答錯的假名會自動進佇列，依 1 分鐘 → 10 分鐘 → 1 小時 → 4 小時 → 9 小時 → 1 天 → 3 天 → 7 天 → 21 天 的間隔再考。1 小時以上的間隔會隨機錯開 ±15%，讓複習分散在一天的不同時段，不會一次全部到期。到期時答對就升一階，答錯回到第一階，9 階都答對就「畢業」移出。</Note>
        <div style={{ marginTop: 10 }}>
          <Btn kind="primary" label={on ? "收起" : due.length ? `開始複習（${due.length}）` : keys.length ? "提前練佇列中的字" : "先練幾個難字"} onClick={() => setOn(!on)} />
        </div>
      </Card>
      {on && !due.length ? <Note>🎉 目前沒有到期的假名；現在答對不會升階，可以稍後再回來。</Note> : null}
      {on ? <QuizRunner key="srs" gen={gen} onResult={(q: Q, ok: boolean) => { if (q.kana) bumpWeak(q.kana, ok); }} /> : null}
    </div>
  );
}
function KanaDash(props: { onPick: (row: string, s: Script) => void }) {
  const t = useGrokTheme();
  useDB();
  const col = (scr: "h" | "k") => {
    const rs = ROWS.map((r: Row) => {
      const cells = r.cells.filter((c: Kana | null): c is Kana => c !== null);
      const v = cells.reduce((s: number, k: Kana) => s + mastery(scr === "h" ? k.h : k.k), 0) / Math.max(1, cells.length);
      return { r, v };
    });
    const all = rs.reduce((s: { v: number; n: number }, x: { r: Row; v: number }) => ({ v: s.v + x.v * x.r.cells.filter((c: Kana | null) => c !== null).length, n: s.n + x.r.cells.filter((c: Kana | null) => c !== null).length }), { v: 0, n: 0 });
    const name = scr === "h" ? "平假名" : "片假名";
    return (
      <Card title={`${name}掌握度 ${Math.round((all.v / Math.max(1, all.n)) * 100)}%`}>
        <div style={{ display: "grid", gap: 6 }}>
          {rs.map(({ r, v }: { r: Row; v: number }) => (
            <button key={r.id} type="button" aria-label={`${name} ${r.name} 掌握度 ${Math.round(v * 100)}%，點一下練這一行`} onClick={() => props.onPick(r.id, scr === "h" ? "hira" : "kata")} style={{ font: "inherit", cursor: "pointer", display: "grid", gridTemplateColumns: "84px 1fr 42px", gap: 8, alignItems: "center", background: "transparent", border: "none", color: t.text.primary, padding: "2px 0", textAlign: "left" }}>
              <span lang="ja" style={{ fontFamily: JA_FONT, fontSize: 14 }}>{scr === "k" ? toKata(r.name) : r.name}{medal(v) ? " " + medal(v) : ""}</span>
              <Bar v={v} color={v >= 0.8 ? t.text.success : v >= 0.4 ? t.text.accent : t.text.danger} />
              <span style={{ fontSize: 12, color: t.text.secondary, textAlign: "right" }}>{Math.round(v * 100)}%</span>
            </button>
          ))}
        </div>
      </Card>
    );
  };
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <BadgeWall />
      <Note>掌握度＝答對率 × 練習量（每個字至少答 3 次才算滿），目前列為弱點的字打 5 折。點任何一行就直接進入該行的認讀測驗。</Note>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: 12 }}>
        {col("h")}
        {col("k")}
      </div>
    </div>
  );
}
function MnemoPanel() {
  const t = useGrokTheme();
  const hard = Object.keys(MNEMO);
  const all = ALL_KANA.filter((k: Kana) => ORIG[k.k] !== undefined);
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <Card title={`最難記的片假名・${hard.length} 個記憶法`}>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))", gap: 10 }}>
          {hard.map((c: string) => (
            <div key={c} style={{ border: `1px solid ${t.border.subtle}`, borderRadius: 10, padding: 10, display: "flex", gap: 10 }}>
              <button type="button" aria-label={`播放 ${c}`} onClick={() => speak(c)} style={{ font: "inherit", cursor: "pointer", background: "transparent", border: "none", color: t.text.primary, padding: 0, textAlign: "center", minWidth: 48 }}>
                <div lang="ja" style={{ fontFamily: JA_FONT, fontSize: 40, lineHeight: 1.1 }}>{c}</div>
                <div style={{ fontSize: 12, color: t.text.secondary }}>{ROMA[c] ?? ""}・{ORIG[c] ?? ""}</div>
              </button>
              <div style={{ fontSize: 13, lineHeight: 1.6, color: t.text.secondary }}>{MNEMO[c]}</div>
            </div>
          ))}
        </div>
      </Card>
      <Card title="片假名字源表（每個片假名都取自一個漢字的一部分）">
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(64px, 1fr))", gap: 6 }}>
          {all.map((k: Kana) => (
            <button key={k.k} type="button" aria-label={`${k.k} ${k.r}，取自 ${ORIG[k.k] ?? ""}`} onClick={() => speak(k.k)} style={{ font: "inherit", cursor: "pointer", border: `1px solid ${t.border.subtle}`, borderRadius: 8, padding: "6px 2px", background: t.bg.base, color: t.text.primary }}>
              <div lang="ja" style={{ fontFamily: JA_FONT, fontSize: 22 }}>{k.k}<span style={{ fontSize: 13, color: t.text.accent, marginLeft: 4 }}>{ORIG[k.k]}</span></div>
              <div style={{ fontSize: 11, color: t.text.secondary }}>{k.r}</div>
            </button>
          ))}
        </div>
        <div style={{ marginTop: 8 }}><Note>ン 的字源有不同說法（常見說法是「尓」），其餘為一般通說。</Note></div>
      </Card>
    </div>
  );
}
