/* ============ 錯題・成績 ============ */
function WrongCards(props: { list: WrongItem[] }) {
  const t = useGrokTheme();
  const [i, setI] = useState(0);
  const [show, setShow] = useState(false);
  const n = props.list.length;
  const w = n ? props.list[i % n] : undefined;
  if (!w) return <Note>這個篩選裡沒有錯題了 🎉</Note>;
  return (
    <div style={{ border: `1.5px solid ${t.border.default}`, borderRadius: 12, padding: 14, marginBottom: 12 }}>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, color: t.text.accent }}>
        <span>{SEC_NAME[w.sec]}・錯 {w.n} 次</span>
        <span style={{ color: t.text.secondary }}>{(i % n) + 1} / {n}</span>
      </div>
      <div lang="ja" style={{ fontFamily: JA_FONT, whiteSpace: "pre-line", margin: "8px 0", fontSize: 17, lineHeight: 2 }}>
        <Rich text={w.prompt} />
      </div>
      {show ? (
        <div role="status" aria-live="polite" style={{ fontSize: 14, marginBottom: 8 }}>
          正解：<b lang="ja" style={{ fontFamily: JA_FONT }}><Rich text={w.ans} /></b>
          {w.exp ? <div style={{ whiteSpace: "pre-line", color: t.text.secondary, fontSize: 13, marginTop: 4 }}><Rich text={w.exp} /></div> : null}
        </div>
      ) : null}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        {!show ? (
          <Btn kind="primary" label="想好了，看答案" onClick={() => setShow(true)} />
        ) : (
          <span style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            <Btn
              kind="primary"
              label="✓ 會了（移出錯題本）"
              onClick={() => {
                DB.wrong = DB.wrong.filter((x: WrongItem) => x.id !== w.id);
                commit();
                setShow(false);
              }}
            />
            <Btn
              label="✗ 還不熟，下一題"
              onClick={() => {
                setI(i + 1);
                setShow(false);
              }}
            />
          </span>
        )}
        {w.prompt ? <Speak text={plain(w.prompt).replace(/[🎧（）　]/gu, " ")} /> : null}
      </div>
    </div>
  );
}
function ReviewTab(props: { go: (tab: string, km?: KMode) => void }) {
  const t = useGrokTheme();
  const db = useDB();
  const [f, setF] = useState("all");
  const [cards, setCards] = useState(false);
  const weakList = Object.keys(db.weak)
    .filter((c: string) => weakScore(c) > 0)
    .sort((a: string, b: string) => weakScore(b) - weakScore(a));
  const due = srsDue().length;
  const list = db.wrong.filter((w: WrongItem) => f === "all" || w.sec === f);
  const opts: [string, string][] = [["all", `全部（${db.wrong.length}）`], ...SEC_LIST.map((s: Sec): [string, string] => [s, `${SEC_NAME[s]}（${db.wrong.filter((w: WrongItem) => w.sec === s).length}）`])];
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(130px, 1fr))", gap: 8 }}>
        {SEC_LIST.map((s: Sec) => {
          const st = db.stats[s] ?? { c: 0, w: 0 };
          const n = st.c + st.w;
          return (
            <Card key={s} style={{ padding: 12 }}>
              <div style={{ fontSize: 12, color: t.text.secondary }}>{SEC_NAME[s]}</div>
              <div style={{ fontSize: 24, fontWeight: 600 }}>{n ? Math.round((st.c / n) * 100) + "%" : "—"}</div>
              <div style={{ fontSize: 12, color: t.text.secondary }}>
                ✓{st.c}　✗{st.w}
              </div>
            </Card>
          );
        })}
      </div>
      <Card title={`50音弱點・複習佇列（弱點 ${weakList.length}、到期 ${due}）`}>
        {weakList.length ? (
          <div lang="ja" style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
            {weakList.slice(0, 48).map((c: string) => (
              <span key={c} style={{ fontFamily: JA_FONT, fontSize: 20, padding: "0 8px", border: `1px solid ${t.border.subtle}`, borderRadius: 8 }}>
                {c}
                <span style={{ fontSize: 11, color: t.text.secondary, marginLeft: 3 }}>{ROMA[c] ?? ""}</span>
              </span>
            ))}
          </div>
        ) : (
          <Note>目前沒有弱點假名。</Note>
        )}
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 10 }}>
          <Btn kind="primary" label={`⏰ 複習到期假名（${due}）`} onClick={() => props.go("kana", "srs")} />
          <Btn label="弱點假名特訓" onClick={() => props.go("kana", "weak")} />
          <Btn label="📊 假名掌握度" onClick={() => props.go("kana", "dash")} />
        </div>
      </Card>
      <Card title="錯題本（各區統一）">
        <Note>單字、文法、模擬題、聽力、歌曲答錯的題目都會自動放進這裡；之後在練習中答對同一題會自動移除。假名的錯誤則記在上方「弱點・複習佇列」。可用「翻卡複習」一題一題自我檢查。</Note>
        <div style={{ margin: "10px 0", display: "grid", gap: 8 }}>
          <Chips small value={f} onChange={setF} options={opts} />
          <div>
            <Btn on={cards} label={cards ? "✓ 翻卡複習中（點此收起）" : `🃏 翻卡複習（${list.length}）`} onClick={() => setCards(!cards)} />
          </div>
        </div>
        {cards ? <WrongCards key={f} list={list} /> : null}
        {list.length ? (
          <div style={{ display: "grid", gap: 8 }}>
            {list.map((w: WrongItem) => (
              <div key={w.id} style={{ border: `1px solid ${t.border.subtle}`, borderRadius: 10, padding: 10 }}>
                <div style={{ display: "flex", justifyContent: "space-between", gap: 8 }}>
                  <span style={{ fontSize: 12, color: t.text.accent }}>
                    {SEC_NAME[w.sec]}・錯 {w.n} 次
                  </span>
                  <button
                    type="button"
                    onClick={() => {
                      DB.wrong = DB.wrong.filter((x: WrongItem) => x.id !== w.id);
                      commit();
                    }}
                    style={{ font: "inherit", fontSize: 12, cursor: "pointer", background: "transparent", border: "none", color: t.text.secondary }}
                  >
                    移除
                  </button>
                </div>
                <div lang="ja" style={{ fontFamily: JA_FONT, whiteSpace: "pre-line", margin: "4px 0" }}>
                  <Rich text={w.prompt} />
                </div>
                <div style={{ fontSize: 14 }}>
                  正解：<b><Rich text={w.ans} /></b>
                </div>
                {w.exp ? <div style={{ fontSize: 13, color: t.text.secondary, whiteSpace: "pre-line", marginTop: 4 }}><Rich text={w.exp} /></div> : null}
              </div>
            ))}
          </div>
        ) : (
          <Note>這裡目前是空的，繼續保持！</Note>
        )}
        <div style={{ display: "flex", gap: 8, marginTop: 12, flexWrap: "wrap" }}>
          {db.wrong.length ? (
            <Btn
              label="清空錯題本"
              onClick={() => {
                DB.wrong = [];
                commit();
              }}
            />
          ) : null}
          <Btn
            label="重設全部成績"
            onClick={() => {
              DB.stats = {};
              commit();
            }}
          />
        </div>
      </Card>
      <BackupCard />
    </div>
  );
}
function BackupCard() {
  const t = useGrokTheme();
  const [txt, setTxt] = useState("");
  const [msg, setMsg] = useState("");
  const [sure, setSure] = useState(false);
  const doExport = () => {
    const s = JSON.stringify({ app: "n3_practice", v: 1, at: new Date().toISOString(), db: DB });
    setTxt(s);
    setSure(false);
    try {
      const url = URL.createObjectURL(new Blob([s], { type: "application/json" }));
      const a = document.createElement("a");
      a.href = url;
      a.download = `n3-progress-${today()}.json`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      window.setTimeout(() => URL.revokeObjectURL(url), 3000);
      setMsg("已產生備份檔。如果瀏覽器沒有下載，請複製下方文字自行保存。");
    } catch {
      setMsg("無法直接下載，請複製下方文字自行保存。");
    }
  };
  const copy = () => {
    try {
      navigator.clipboard.writeText(txt).then(
        () => setMsg("已複製到剪貼簿。"),
        () => setMsg("無法自動複製，請手動全選後複製。")
      );
    } catch {
      setMsg("無法自動複製，請手動全選後複製。");
    }
  };
  const parse = (): Partial<DBT> | null => {
    try {
      const p = JSON.parse(txt) as { db?: Partial<DBT> } & Partial<DBT>;
      const d: Partial<DBT> | undefined = p && typeof p === "object" ? (p.db ?? p) : undefined;
      if (!d || typeof d.stats !== "object" || !Array.isArray(d.wrong)) return null;
      return d;
    } catch {
      return null;
    }
  };
  const doImport = () => {
    const d = parse();
    if (!d) {
      setSure(false);
      setMsg("❌ 格式不正確：請貼上從這裡匯出的完整備份內容。");
      return;
    }
    if (!sure) {
      setSure(true);
      setMsg("⚠️ 匯入會覆蓋這個瀏覽器目前的進度，確定的話請再按一次「確定匯入」。");
      return;
    }
    DB = { ...freshDB(), ...d, onb: 1 };
    commit();
    setSure(false);
    setMsg("✅ 已匯入進度。");
  };
  const onFile = (e: ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0];
    if (!f) return;
    const r = new FileReader();
    r.onload = () => {
      setTxt(String(r.result ?? ""));
      setSure(false);
      setMsg("已讀取檔案，按「匯入」套用。");
    };
    r.readAsText(f);
  };
  return (
    <Card title="💾 備份與還原進度（換手機／電腦時使用）">
      <div style={{ display: "grid", gap: 8 }}>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
          <Btn kind="primary" label="匯出進度" onClick={doExport} />
          <Btn label="複製文字" onClick={copy} />
          <Btn label={sure ? "確定匯入" : "匯入"} onClick={doImport} />
          <label style={{ fontSize: 13, color: t.text.secondary }}>
            或選檔案：
            <input type="file" accept="application/json,.json,.txt" onChange={onFile} aria-label="選擇備份檔" style={{ fontSize: 13, color: t.text.secondary }} />
          </label>
        </div>
        <textarea
          value={txt}
          aria-label="備份內容"
          onChange={(e: ChangeEvent<HTMLTextAreaElement>) => {
            setTxt(e.target.value);
            setSure(false);
          }}
          placeholder="按「匯出進度」後，備份內容會顯示在這裡；要還原時，把備份內容貼在這裡再按「匯入」。"
          rows={3}
          style={{ font: "inherit", fontSize: 12, fontFamily: "monospace", width: "100%", boxSizing: "border-box", padding: 8, borderRadius: 8, border: `1px solid ${t.border.default}`, background: t.bg.base, color: t.text.primary }}
        />
        {msg ? (
          <div role="status" aria-live="polite" style={{ fontSize: 13, color: t.text.secondary }}>
            {msg}
          </div>
        ) : null}
      </div>
    </Card>
  );
}
function GlobalSearch() {
  const t = useGrokTheme();
  const [q, setQ] = useState("");
  const [open, setOpen] = useState("");
  const ref = useRef<HTMLInputElement | null>(null);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const tg = e.target as HTMLElement | null;
      if (tg && (tg.tagName === "INPUT" || tg.tagName === "TEXTAREA")) {
        if (e.key === "Escape" && tg === ref.current) {
          setQ("");
          ref.current?.blur();
        }
        return;
      }
      if (e.key === "/") {
        e.preventDefault();
        ref.current?.focus();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);
  const qq = q.trim();
  const hits = useMemo(() => {
    const empty = { v: [] as Vocab[], g: [] as Gram[], k: [] as KW[] };
    if (!qq) return empty;
    const kq = toKata(qq);
    const bare = qq.replace(/[～〜~]/g, "");
    const lo = qq.toLowerCase();
    const rank = (v: Vocab) => (v.w === qq || v.r === qq ? 0 : v.w.startsWith(qq) || v.r.startsWith(qq) ? 1 : v.w.includes(qq) || v.r.includes(qq) ? 2 : v.m.includes(qq) ? 3 : 4);
    const v = VOCAB.filter((x: Vocab) => x.w.includes(qq) || x.r.includes(qq) || x.m.includes(qq) || (qq.length >= 2 && plain(x.ex).includes(qq)))
      .sort((a: Vocab, b: Vocab) => rank(a) - rank(b))
      .slice(0, 30);
    const g = GRAMMAR.filter((x: Gram) => (bare.length > 0 && x.pat.replace(/[～〜]/g, "").includes(bare)) || x.m.includes(qq) || (qq.length >= 2 && plain(x.full).includes(qq))).slice(0, 15);
    const k = KWORDS.filter((x: KW) => x.k.includes(kq) || x.m.includes(qq) || (/^[a-z]{2,}$/.test(lo) && normRoma(x.r).includes(normRoma(lo)))).slice(0, 15);
    return { v, g, k };
  }, [qq]);
  const rowBtn = { font: "inherit", cursor: "pointer", background: "transparent", border: "none", color: t.text.primary, padding: "4px 0", textAlign: "left", display: "flex", gap: 10, alignItems: "baseline", flexWrap: "wrap", width: "100%" } as const;
  const head = (s: string) => <div style={{ fontSize: 12, fontWeight: 600, color: t.text.accent, margin: "8px 0 2px" }}>{s}</div>;
  const none = qq && !hits.v.length && !hits.g.length && !hits.k.length;
  return (
    <div style={{ display: "grid", gap: 8 }}>
      <input
        ref={ref}
        type="search"
        value={q}
        onChange={(e: ChangeEvent<HTMLInputElement>) => setQ(e.target.value)}
        placeholder="🔍 搜尋單字、文法、外來語（中文／日文／假名／羅馬字）"
        aria-label="搜尋單字、文法、外來語"
        style={{ font: "inherit", fontSize: 15, padding: "10px 12px", borderRadius: 10, border: `1px solid ${t.border.default}`, background: t.bg.elevated, color: t.text.primary, width: "100%", boxSizing: "border-box" }}
      />
      {qq ? (
        <Card title={`搜尋「${qq}」：單字 ${hits.v.length}・文法 ${hits.g.length}・外來語 ${hits.k.length}`}>
          <div style={{ maxHeight: 420, overflowY: "auto" }}>
            {none ? <Note>找不到符合的項目。可以試試中文意思、平假名讀音或文法（例如「ように」）。</Note> : null}
            {hits.v.length ? head("單字") : null}
            {hits.v.map((v: Vocab) => (
              <div key={v.id} style={{ borderBottom: `1px solid ${t.border.subtle}` }}>
                <button type="button" aria-expanded={open === v.id} onClick={() => setOpen(open === v.id ? "" : v.id)} style={rowBtn}>
                  <Ruby w={v.w} r={v.r} size={18} />
                  <span style={{ fontSize: 14 }}>{v.m}</span>
                  <span style={{ fontSize: 12, color: t.text.secondary }}>{v.p}</span>
                </button>
                {open === v.id ? (
                  <div style={{ padding: "0 0 8px 8px", fontSize: 14, lineHeight: 1.9 }}>
                    <span lang="ja" style={{ fontFamily: JA_FONT }}>
                      <RubyText text={v.ex} />
                    </span>{" "}
                    <Speak text={v.ex} />
                    <div style={{ color: t.text.secondary }}>{v.tr}</div>
                  </div>
                ) : null}
              </div>
            ))}
            {hits.g.length ? head("文法") : null}
            {hits.g.map((g: Gram) => (
              <div key={g.id} style={{ borderBottom: `1px solid ${t.border.subtle}` }}>
                <button type="button" aria-expanded={open === g.id} onClick={() => setOpen(open === g.id ? "" : g.id)} style={rowBtn}>
                  <span lang="ja" style={{ fontFamily: JA_FONT, fontSize: 16, fontWeight: 600 }}>{g.pat}</span>
                  <span style={{ fontSize: 14 }}>{g.m}</span>
                </button>
                {open === g.id ? (
                  <div style={{ padding: "0 0 8px 8px", fontSize: 14, lineHeight: 1.9 }}>
                    <div style={{ color: t.text.secondary }}>接續：{g.conn}</div>
                    <span lang="ja" style={{ fontFamily: JA_FONT }}>
                      <RubyText text={g.full} />
                    </span>{" "}
                    <Speak text={g.full} />
                    <div style={{ color: t.text.secondary }}>{g.tr}</div>
                  </div>
                ) : null}
              </div>
            ))}
            {hits.k.length ? head("外來語・菜單・地名") : null}
            {hits.k.map((k: KW) => (
              <div key={k.k} style={{ borderBottom: `1px solid ${t.border.subtle}`, display: "flex", gap: 10, alignItems: "baseline", padding: "4px 0", flexWrap: "wrap" }}>
                <span lang="ja" style={{ fontFamily: JA_FONT, fontSize: 17 }}>{k.k}</span>
                <span style={{ fontSize: 13, color: t.text.secondary }}>{k.r}</span>
                <span style={{ fontSize: 14 }}>{k.m}</span>
                <Speak text={k.k} />
              </div>
            ))}
          </div>
          <div style={{ marginTop: 8 }}>
            <Btn small label="清除搜尋" onClick={() => setQ("")} />
          </div>
        </Card>
      ) : null}
    </div>
  );
}
function Onboarding(props: { go: (tab: string, km?: KMode) => void }) {
  const t = useGrokTheme();
  const done = (tab?: string, km?: KMode) => {
    DB.onb = 1;
    commit();
    if (tab) {
      props.go(tab, km);
      window.setTimeout(() => document.querySelector('[role="tablist"][aria-label="練習區"]')?.scrollIntoView({ block: "start", behavior: "smooth" }), 80);
    }
  };
  const opts: [string, string, string, KMode | undefined][] = [
    ["🔤 片假名常認錯", "從片假名認讀開始（あ～な行），答錯的字自動排進複習佇列", "kana", "quiz"],
    ["📖 平假名也會忘", "先看五十音表，點字聽發音，再做配對練習", "kana", "table"],
    ["📝 假名沒問題", "直接背 N3 單字（可依主題、詞性篩選）", "vocab", undefined],
    ["⏱ 想先測程度", "到模擬考選「⏱ 計時模考」，看三個得分區分", "mock", undefined],
  ];
  return (
    <Card title="👋 歡迎！先選一個起點（之後隨時可以換）">
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 8 }}>
        {opts.map(([a, b, tab, km]: [string, string, string, KMode | undefined]) => (
          <button key={a} type="button" onClick={() => done(tab, km)} style={{ font: "inherit", cursor: "pointer", textAlign: "left", border: `1px solid ${t.border.default}`, borderRadius: 12, padding: "10px 12px", background: t.bg.base, color: t.text.primary, display: "grid", gap: 4 }}>
            <span style={{ fontWeight: 600 }}>{a}</span>
            <span style={{ fontSize: 13, color: t.text.secondary }}>{b}</span>
          </button>
        ))}
      </div>
      <ul style={{ margin: "10px 0 6px", paddingLeft: 20, fontSize: 13, lineHeight: 1.8, color: t.text.secondary }}>
        <li>每天看「📅 今日任務」，做完就能維持連續天數。</li>
        <li>電腦鍵盤：1–4 作答、Enter 下一題、R 重播聲音、/ 搜尋。</li>
        <li>進度只存在這個瀏覽器；換裝置前到「錯題・成績」→「備份與還原」匯出。</li>
      </ul>
      <Btn small label="略過導覽" onClick={() => done()} />
    </Card>
  );
}

